(function(){const A=[{"id":"sp9-potok-teni","n":"Поток Тени","l":3,"sc":"Иллюзия","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 некротика","cl":["Колдун","Бард","Чародей"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Мудрость): 7к6 урона (некротика) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Поток","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-uzy-krovi","n":"Узы Крови","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Капля вашей крови.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 некротика","cl":["Колдун","Чародей","Жрец"],"ds":"Узы (крови) охватывают существо: спасбросок (Телосложение) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (некротика) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Узы","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-raspad-molniy","n":"Распад Молний","l":6,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 электричество","cl":["Чародей","Друид"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (электричество) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-duh-groma","n":"Дух Грома","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 звук","cl":["Жрец","Друид","Следопыт"],"ds":"Вы призываете духа (грома) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (звук). Иммунитет к урону «звук». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-kleymo-ineya","n":"Клеймо Инея","l":1,"sc":"Воплощение","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 холод","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (холод), и цель совершает спасбросок (Телосложение) — при провале она покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Клеймо","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-avatar-plameni","n":"Аватар Пламени","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 огонь","cl":["Чародей","Колдун"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «огонь», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (огонь). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-ubezhische-kostey","n":"Убежище Костей","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Фаланга пальца.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: склеп из костей, мимо которого нежить проходит, не замечая. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-chute-pustoty","n":"Чутьё Пустоты","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Колдун","Волшебник","Друид"],"ds":"Вы чувствуете порталы, разрывы между планами и пространственные карманы в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-katastrofa-zvezd","n":"Катастрофа Звёзд","l":7,"sc":"Прорицание","t":"1 действие","r":"300 м","c":"ВСМ","m":"Щепоть звёздной пыли.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 излучение","cl":["Бард","Жрец"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Мудрость) — 12к6 урона (излучение) при провале (и цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Мудрость","atk":false,"mech":"Катастрофа","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-opros-razuma","n":"Опрос Разума","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы обращаетесь к стихии: вопрошаете спящего или задумчивого существа (вы видите один его сон или мысль). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-shag-yada","n":"Шаг Яда","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 яд","cl":["Следопыт","Колдун","Изобретатель"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Телосложение) или получает 1к6 урона (яд). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Шаг","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-vlast-voln","n":"Власть Волн","l":8,"sc":"Вызов","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 дробящий","cl":["Чародей","Жрец"],"ds":"Вы повелеваете стихией (волн) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Сила), 6к10 урона (дробящий) при провале и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству, половина при успехе.","save":"Сила","atk":false,"mech":"Власть","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-burya-vetra","n":"Буря Ветра","l":4,"sc":"Воплощение","t":"1 действие","r":"90 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 звук","cl":["Чародей","Друид","Изобретатель"],"ds":"Буря (ветра) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Сила): 3к6 урона (звук) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Буря","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-sfera-kamnya","n":"Сфера Камня","l":2,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Изобретатель","Друид","Волшебник"],"ds":"Сфера (камня) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Сила): 2к6 урона (дробящий) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Сфера","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-apokalipsis-duhov","n":"Апокалипсис Духов","l":9,"sc":"Вызов","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 психический","cl":["Бард","Друид"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Мудрость): 14к6 урона (психический) плюс 14к6 силовым полем при провале (и цель испугана вами до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Мудрость","atk":false,"mech":"Апокалипсис","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-vrata-mirazhey","n":"Врата Миражей","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 психический","cl":["Бард","Колдун","Чародей"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (миражей). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (психический). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-zavesa-sveta","n":"Завеса Света","l":2,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Следопыт"],"ds":"Куб с ребром 6 м заполняется завесой (света): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Телосложение) — при провале оно излучает тусклый свет в 1,5 м и не может стать невидимой до конца её следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Завеса","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-kasanie-shipov","n":"Касание Шипов","l":0,"sc":"Преобразование","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 колющий","cl":["Друид","Бард","Жрец"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (колющий), и цель опутывается колючими лозами: скорость 0 до конца её следующего хода. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-tropa-run","n":"Тропа Рун","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Резец и кусочек кости.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Жрец","Волшебник"],"ds":"До 8 согласных существ отправляются в путь по цепи рун: группа переносится к руне, которую вы начертали раньше. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-morok-vremeni","n":"Морок Времени","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Волшебник","Чародей"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также замедляется: не может совершать бонусных действий до конца своего следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-otmetina-teni","n":"Отметина Тени","l":0,"sc":"Иллюзия","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 некротика","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Вы отмечаете существо знаком (тени). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (некротика). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-kara-krovi","n":"Кара Крови","l":5,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Одно существо совершает спасбросок (Телосложение): 8к8 урона (некротика) при провале (и цель не может восстанавливать хиты до конца своего следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Телосложение","atk":false,"mech":"Кара","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-strazh-molniy","n":"Страж Молний","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 электричество","cl":["Друид","Волшебник","Следопыт"],"ds":"Вы призываете крошечного духа (молний): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (электричество)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-obereg-groma","n":"Оберег Грома","l":0,"sc":"Воплощение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «звук», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-svyatilische-ineya","n":"Святилище Инея","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кристалл льда.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Телосложение) — при провале они покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Телосложение","atk":false,"mech":"Святилище","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-vzryv-plameni","n":"Взрыв Пламени","l":3,"sc":"Воплощение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Щепоть серы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 огонь","cl":["Чародей","Колдун","Изобретатель"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Ловкость), получая 6к6 урона (огонь) при провале (и цель загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Ловкость","atk":false,"mech":"Взрыв","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-kope-kostey","n":"Копьё Костей","l":1,"sc":"Некромантия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 колющий","cl":["Колдун","Жрец","Волшебник"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (колющий). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-dvoynik-pustoty","n":"Двойник Пустоты","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 силовое поле","cl":["Колдун","Следопыт","Паладин"],"ds":"Вы создаёте двойника из пустоты, имеющей форму, но не вес. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (силовое поле) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-potok-zvezd","n":"Поток Звёзд","l":3,"sc":"Прорицание","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 излучение","cl":["Бард","Жрец","Друид"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Мудрость): 7к6 урона (излучение) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Поток","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-uzy-razuma","n":"Узы Разума","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 психический","cl":["Бард","Чародей","Колдун"],"ds":"Узы (разума) охватывают существо: спасбросок (Интеллект) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (психический) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Узы","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-raspad-yada","n":"Распад Яда","l":6,"sc":"Преобразование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Жало пчелы.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 яд","cl":["Колдун","Чародей"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (яд) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-duh-voln","n":"Дух Волн","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 дробящий","cl":["Жрец","Друид","Следопыт"],"ds":"Вы призываете духа (волн) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (дробящий). Иммунитет к урону «дробящий». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-kleymo-vetra","n":"Клеймо Ветра","l":1,"sc":"Воплощение","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 звук","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (звук), и цель совершает спасбросок (Сила) — при провале она отталкивается на 4,5 м в выбранном вами направлении. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Клеймо","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-avatar-kamnya","n":"Аватар Камня","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 дробящий","cl":["Друид","Волшебник"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «дробящий», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (дробящий). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-aura-duhov","n":"Аура Духов","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Бард","Жрец","Друид"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «психический» и преимущество на спасброски от эффектов, из-за которых цель испугана вами до конца её следующего хода. Враг, начинающий ход в ауре, совершает спасбросок (Мудрость) или получает 2к6 урона (психический). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Аура","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-golos-mirazhey","n":"Голос Миражей","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Чародей"],"ds":"Ваш голос наполняется силой стихии (миражей). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-carstvo-sveta","n":"Царство Света","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Святой символ.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Бард"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (света) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Телосложение","atk":false,"mech":"Царство","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-perenos-shipov","n":"Перенос Шипов","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по корням на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-balzam-run","n":"Бальзам Рун","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Следопыт","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «силовое поле» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-slovo-vremeni","n":"Слово Времени","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 силовое поле","cl":["Бард","Чародей"],"ds":"Вы произносите истинное слово (времени). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (силовое поле) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-oblik-teni","n":"Облик Тени","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 некротика","cl":["Следопыт","Колдун","Паладин"],"ds":"Вы принимаете облик (тени): сопротивление урону «некротика» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (некротика). Попадание: цель окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-cep-krovi","n":"Цепь Крови","l":2,"sc":"Некромантия","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (некротика) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Телосложение) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":true,"mech":"Цепь","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-iskra-molniy","n":"Искра Молний","l":0,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 электричество","cl":["Изобретатель","Чародей","Волшебник"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (электричество). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-stena-groma","n":"Стена Грома","l":4,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 звук","cl":["Чародей","Бард","Жрец"],"ds":"Стена (грома) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Телосложение): 5к8 урона (звук) при провале (и цель отбрасывается на 3 м от источника и не может совершать реакции до начала своего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Стена","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-oruzhie-ineya","n":"Оружие Инея","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 холод","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (холод). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Телосложение): при провале она покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-vspyshka-plameni","n":"Вспышка Пламени","l":0,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 огонь","cl":["Изобретатель","Чародей","Колдун"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Ловкость), получая 1к6 урона (огонь) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Ловкость","atk":false,"mech":"Вспышка","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-tropa-kostey","n":"Тропа Костей","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Фаланга пальца.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Волшебник"],"ds":"До 8 согласных существ отправляются в путь по костяной тропе: призрачный мост из костей ведёт группу через пропасти и реки. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-morok-pustoty","n":"Морок Пустоты","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Чародей","Колдун","Волшебник"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также не может телепортироваться и перемещаться между планами до конца её следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-otmetina-zvezd","n":"Отметина Звёзд","l":0,"sc":"Прорицание","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 излучение","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (звёзд). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (излучение). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-kara-razuma","n":"Кара Разума","l":5,"sc":"Очарование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 психический","cl":["Чародей","Бард","Колдун"],"ds":"Одно существо совершает спасбросок (Интеллект): 8к8 урона (психический) при провале (и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Интеллект","atk":false,"mech":"Кара","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-strazh-yada","n":"Страж Яда","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 яд","cl":["Следопыт","Колдун","Друид"],"ds":"Вы призываете крошечного духа (яда): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (яд)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-obereg-voln","n":"Оберег Волн","l":0,"sc":"Вызов","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «дробящий», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-svyatilische-vetra","n":"Святилище Ветра","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Перо.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Изобретатель","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Сила) — при провале они отталкивается на 4,5 м в выбранном вами направлении и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Сила","atk":false,"mech":"Святилище","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-vzryv-kamnya","n":"Взрыв Камня","l":3,"sc":"Преобразование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Кусочек гранита.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 дробящий","cl":["Изобретатель","Друид","Чародей"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Сила), получая 6к6 урона (дробящий) при провале (и цель сбивается с ног, если она Большая или меньше) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Взрыв","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-volna-duhov","n":"Волна Духов","l":1,"sc":"Вызов","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 психический","cl":["Бард","Колдун","Жрец"],"ds":"Существа в конусе совершают спасбросок (Мудрость): при провале 2к6 урона (психический) и цель испугана вами до конца её следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Мудрость","atk":false,"mech":"Волна","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-svyaz-mirazhey","n":"Связь Миражей","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Кусочек стекла.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы вопрошаете отражение в воде или зеркале (оно показывает сцену, которую видело), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-kokon-sveta","n":"Кокон Света","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Следопыт"],"ds":"Кокон (света) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Телосложение) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Кокон","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-pokrov-shipov","n":"Покров Шипов","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Шип розы.","d":"1 час","conc":false,"rit":false,"dmg":"5 колющий","cl":["Паладин","Волшебник","Изобретатель"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (колющий); у вас сопротивление урону «колющий». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-kolco-run","n":"Кольцо Рун","l":6,"sc":"Ограждение","t":"1 действие","r":"45 м","c":"ВСМ","m":"Резец и кусочек кости.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 силовое поле","cl":["Жрец","Чародей"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Интеллект): при провале оно получает 6к8 урона (силовое поле), не проходит и получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Интеллект","atk":false,"mech":"Кольцо","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-ubezhische-vremeni","n":"Убежище Времени","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Песчинка из песочных часов.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Бард","Изобретатель","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: внутри время течёт так, что 8 часов отдыха занимают снаружи 2 часа. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-chute-teni","n":"Чутьё Тени","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Следопыт","Колдун","Друид"],"ds":"Вы чувствуете тьму, невидимых существ в тени и проходы, скрытые темнотой в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-katastrofa-krovi","n":"Катастрофа Крови","l":7,"sc":"Некромантия","t":"1 действие","r":"300 м","c":"ВСМ","m":"Капля вашей крови.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 некротика","cl":["Чародей","Колдун"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Телосложение) — 12к6 урона (некротика) при провале (и цель не может восстанавливать хиты до конца своего следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Телосложение","atk":false,"mech":"Катастрофа","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-opros-molniy","n":"Опрос Молний","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек янтаря.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Волшебник","Друид"],"ds":"Вы обращаетесь к стихии: вопрошаете механизм или металл поблизости (он «помнит», кто к нему прикасался). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-shag-groma","n":"Шаг Грома","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 звук","cl":["Бард","Жрец","Друид"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Телосложение) или получает 1к6 урона (звук). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Шаг","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-vlast-ineya","n":"Власть Инея","l":8,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 холод","cl":["Чародей","Друид"],"ds":"Вы повелеваете стихией (инея) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Телосложение), 6к10 урона (холод) при провале и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода, половина при успехе.","save":"Телосложение","atk":false,"mech":"Власть","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-burya-plameni","n":"Буря Пламени","l":4,"sc":"Воплощение","t":"1 действие","r":"90 м","c":"ВСМ","m":"Щепоть серы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 огонь","cl":["Чародей","Изобретатель","Колдун"],"ds":"Буря (пламени) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Ловкость): 3к6 урона (огонь) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Ловкость","atk":false,"mech":"Буря","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-balzam-kostey","n":"Бальзам Костей","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Жрец","Следопыт","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «колющий» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-slovo-pustoty","n":"Слово Пустоты","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 силовое поле","cl":["Чародей","Колдун"],"ds":"Вы произносите истинное слово (пустоты). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (силовое поле) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-oblik-zvezd","n":"Облик Звёзд","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 излучение","cl":["Бард","Жрец","Волшебник"],"ds":"Вы принимаете облик (звёзд): сопротивление урону «излучение» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (излучение). Попадание: цель очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-cep-razuma","n":"Цепь Разума","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 психический","cl":["Чародей","Бард","Колдун"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (психический) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Интеллект) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":true,"mech":"Цепь","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-iskra-yada","n":"Искра Яда","l":0,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 яд","cl":["Колдун","Изобретатель","Друид"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (яд). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-stena-voln","n":"Стена Волн","l":4,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 дробящий","cl":["Чародей","Жрец","Паладин"],"ds":"Стена (волн) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Сила): 5к8 урона (дробящий) при провале (и цель промокает и сбивается с ног; до конца её следующего хода она уязвима к электричеству), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Стена","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-oruzhie-vetra","n":"Оружие Ветра","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 звук","cl":["Следопыт","Паладин","Изобретатель"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (звук). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Сила): при провале она отталкивается на 4,5 м в выбранном вами направлении. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-vspyshka-kamnya","n":"Вспышка Камня","l":0,"sc":"Преобразование","t":"1 действие","r":"На себя (1,5 м)","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 дробящий","cl":["Изобретатель","Друид","Волшебник"],"ds":"Каждое существо по вашему выбору в пределах 1,5 м совершает спасбросок (Сила), получая 1к6 урона (дробящий) при провале. Не требует видеть цели. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"Сила","atk":false,"mech":"Вспышка","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-proklyatie-duhov","n":"Проклятие Духов","l":4,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Бард","Колдун","Жрец"],"ds":"Цель совершает спасбросок Мудрости. При провале ваши атаки и заклинания наносят ей дополнительно 2к6 урона (психический), а в начале каждого её хода она бросает к4: на 1 она испугана вами до конца её следующего хода. «Снятие проклятия» оканчивает эффект. Ячейкой 5 уровня — 8 часов без концентрации, 7+ уровня — 24 часа.","save":"Мудрость","atk":false,"mech":"Проклятие","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-slepok-mirazhey","n":"Слепок Миражей","l":2,"sc":"Преобразование","t":"1 минута","r":"Касание","c":"ВСМ","m":"Кусочек стекла.","d":"8 часов","conc":false,"rit":false,"dmg":"—","cl":["Бард","Колдун","Волшебник"],"ds":"Вы создаёте немагический предмет из иллюзии, ставшей вещественной размером до куба 1,5 м: инструмент, мост, лестницу, ящик или простое оружие. Предмет имеет КД 15 и 30 хитов; через 8 часов он рассыпается. Ячейкой 4+ уровня предмет держится 24 часа, 6+ уровня — постоянно.","save":"","atk":false,"mech":"Слепок","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-maloe-chudo-sveta","n":"Малое Чудо Света","l":0,"sc":"Воплощение","t":"1 действие","r":"9 м","c":"В","m":"","d":"До 1 часа","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Следопыт"],"ds":"Вы творите мелкое чудо: создать мягкое сияние в 6 м, очистить 1 порцию пищи или заставить святой символ засиять. Одновременно активны не более трёх эффектов; вы можете окончить любой действием.","save":"","atk":false,"mech":"Малое Чудо","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-legion-shipov","n":"Легион Шипов","l":5,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Шип розы.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"2к6 колющий","cl":["Следопыт","Друид","Волшебник"],"ds":"Появляются четыре духа (шипов): Маленькие, КД 15, хиты 20, скорость 12 м, иммунитет к урону «колющий». Каждый атакует заклинанием 1,5 м на 2к6 урона (колющий). Действуют в вашу инициативу по вашим мысленным командам (без действия). На больших уровнях: +1 дух за каждый уровень ячейки выше 5-го.","save":"","atk":true,"mech":"Легион","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-pechat-run","n":"Печать Рун","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Резец и кусочек кости.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 силовое поле","cl":["Изобретатель","Жрец","Паладин"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Интеллект): 3к6 урона (силовое поле) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Интеллект","atk":false,"mech":"Печать","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-kope-vremeni","n":"Копьё Времени","l":1,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 силовое поле","cl":["Бард","Изобретатель","Чародей"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (силовое поле). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-dvoynik-teni","n":"Двойник Тени","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 некротика","cl":["Следопыт","Колдун","Бард"],"ds":"Вы создаёте двойника из отвердевшей тени, почти невесомой. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (некротика) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-potok-krovi","n":"Поток Крови","l":3,"sc":"Некромантия","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 некротика","cl":["Чародей","Колдун","Жрец"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Телосложение): 7к6 урона (некротика) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Телосложение","atk":false,"mech":"Поток","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-uzy-molniy","n":"Узы Молний","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 электричество","cl":["Чародей","Следопыт","Друид"],"ds":"Узы (молний) охватывают существо: спасбросок (Ловкость) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (электричество) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Узы","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-raspad-groma","n":"Распад Грома","l":6,"sc":"Воплощение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 звук","cl":["Чародей","Бард"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (звук) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-duh-ineya","n":"Дух Инея","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 холод","cl":["Друид","Волшебник","Следопыт"],"ds":"Вы призываете духа (инея) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (холод). Иммунитет к урону «холод». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-kleymo-plameni","n":"Клеймо Пламени","l":1,"sc":"Воплощение","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 огонь","cl":["Изобретатель","Следопыт","Паладин"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (огонь), и цель совершает спасбросок (Ловкость) — при провале она загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Ловкость","atk":false,"mech":"Клеймо","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-kolco-kostey","n":"Кольцо Костей","l":6,"sc":"Некромантия","t":"1 действие","r":"45 м","c":"ВСМ","m":"Фаланга пальца.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 колющий","cl":["Колдун","Жрец"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Телосложение): при провале оно получает 6к8 урона (колющий), не проходит и становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Кольцо","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-ubezhische-pustoty","n":"Убежище Пустоты","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Чёрная жемчужина.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Волшебник","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: карманное пространство, вход в которое — тёмная щель в воздухе. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-chute-zvezd","n":"Чутьё Звёзд","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Вы чувствуете путевые знаки, направление к цели и предзнаменования в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-katastrofa-razuma","n":"Катастрофа Разума","l":7,"sc":"Очарование","t":"1 действие","r":"300 м","c":"ВСМ","m":"Кусочек мозгового коралла.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 психический","cl":["Бард","Чародей"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Интеллект) — 12к6 урона (психический) при провале (и цель не может совершать реакции и совершает с помехой следующую проверку Интеллекта), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Интеллект","atk":false,"mech":"Катастрофа","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-opros-yada","n":"Опрос Яда","l":3,"sc":"Прорицание","t":"10 минут","r":"Касание","c":"ВСМ","m":"Жало пчелы.","d":"10 минут","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Изобретатель","Колдун"],"ds":"Вы обращаетесь к стихии: вопрошаете яд или болезнь (они говорят, кем и когда созданы). Вы можете задать до трёх вопросов и получаете короткие правдивые ответы, ограниченные тем, что могла «видеть» стихия.","save":"","atk":false,"mech":"Опрос","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-shag-voln","n":"Шаг Волн","l":1,"sc":"Вызов","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к6 дробящий","cl":["Жрец","Друид","Следопыт"],"ds":"Вы телепортируетесь на 9 м в видимое свободное место. Каждое существо в 1,5 м от точки отправления совершает спасбросок (Сила) или получает 1к6 урона (дробящий). На больших уровнях: +3 м дистанции и +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Шаг","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-vlast-vetra","n":"Власть Ветра","l":8,"sc":"Воплощение","t":"1 действие","r":"На себя (1,5 км)","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"6к10 звук","cl":["Чародей","Друид"],"ds":"Вы повелеваете стихией (ветра) в радиусе 1,5 км: создаёте, гасите, перемещаете и формируете её проявления. Действием вы обрушиваете её на существо в 36 м: спасбросок (Сила), 6к10 урона (звук) при провале и цель отталкивается на 4,5 м в выбранном вами направлении, половина при успехе.","save":"Сила","atk":false,"mech":"Власть","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-burya-kamnya","n":"Буря Камня","l":4,"sc":"Преобразование","t":"1 действие","r":"90 м","c":"ВСМ","m":"Кусочек гранита.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"3к6 дробящий","cl":["Изобретатель","Чародей","Друид"],"ds":"Буря (камня) в цилиндре радиусом 6 м и высотой 12 м: местность труднопроходимая. Существо, начинающее ход в буре или впервые входящее в неё за ход, совершает спасбросок (Сила): 3к6 урона (дробящий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 4-го.","save":"Сила","atk":false,"mech":"Буря","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-sfera-duhov","n":"Сфера Духов","l":2,"sc":"Вызов","t":"1 действие","r":"18 м","c":"ВСМ","m":"Благовония.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Колдун","Бард","Жрец"],"ds":"Сфера (духов) диаметром 1,5 м появляется в пределах дистанции. Существо, оканчивающее ход в 1,5 м от неё, совершает спасбросок (Мудрость): 2к6 урона (психический) при провале, половина при успехе. Бонусным действием сфера перемещается на 9 м; если она врезается в существо, оно совершает спасбросок, и сфера останавливается. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Сфера","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-apokalipsis-mirazhey","n":"Апокалипсис Миражей","l":9,"sc":"Иллюзия","t":"1 действие","r":"1,5 км","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"14к6+14к6 психический","cl":["Бард","Волшебник"],"ds":"Вы выбираете до четырёх точек; от каждой расходится сфера радиусом 12 м. Существо в одной или нескольких сферах совершает один спасбросок (Интеллект): 14к6 урона (психический) плюс 14к6 силовым полем при провале (и цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода), половина при успехе. Предметы и строения в области получают двойной урон.","save":"Интеллект","atk":false,"mech":"Апокалипсис","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-vrata-sveta","n":"Врата Света","l":4,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к10 излучение","cl":["Паладин","Жрец","Чародей"],"ds":"Существо совершает спасбросок Харизмы или проваливается в карман-измерение (света). Там оно недееспособно. Когда заклинание оканчивается, цель возвращается и получает 4к10 урона (излучение). Если концентрация продержалась полную минуту, урон удваивается. На больших уровнях: +1 цель за каждый уровень ячейки выше 4-го.","save":"Харизма","atk":false,"mech":"Врата","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-zavesa-shipov","n":"Завеса Шипов","l":2,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Куб с ребром 6 м заполняется завесой (шипов): местность труднопроходимая и слабо заслонённая. Существо, впервые за ход входящее туда, совершает спасбросок (Сила) — при провале оно опутывается колючими лозами: скорость 0 до конца её следующего хода. На больших уровнях: +3 м к ребру куба за каждый уровень ячейки выше 2-го.","save":"Сила","atk":false,"mech":"Завеса","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-kasanie-run","n":"Касание Рун","l":0,"sc":"Ограждение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 силовое поле","cl":["Жрец","Изобретатель","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (силовое поле), и цель получает светящуюся руну: следующая атака по ней до конца вашего следующего хода получает +1к4 к броску. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-tropa-vremeni","n":"Тропа Времени","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Песчинка из песочных часов.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Изобретатель","Бард","Паладин"],"ds":"До 8 согласных существ отправляются в путь «сквозь мгновение»: группа путешествует, а для мира проходит лишь четверть затраченного времени. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-morok-teni","n":"Морок Тени","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Колдун","Волшебник"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также окутывается тенью: помеха на проверки Мудрости (Восприятие) и атаки по существам дальше 9 м. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-otmetina-krovi","n":"Отметина Крови","l":0,"sc":"Некромантия","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 некротика","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (крови). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (некротика). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-kara-molniy","n":"Кара Молний","l":5,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 электричество","cl":["Изобретатель","Чародей","Друид"],"ds":"Одно существо совершает спасбросок (Ловкость): 8к8 урона (электричество) при провале (и цель не может совершать реакции до начала своего следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Ловкость","atk":false,"mech":"Кара","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-strazh-groma","n":"Страж Грома","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Маленький колокольчик.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 звук","cl":["Жрец","Друид","Следопыт"],"ds":"Вы призываете крошечного духа (грома): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (звук)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-obereg-ineya","n":"Оберег Инея","l":0,"sc":"Воплощение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Волшебник","Паладин","Жрец"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «холод», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-svyatilische-plameni","n":"Святилище Пламени","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Щепоть серы.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Ловкость) — при провале они загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Ловкость","atk":false,"mech":"Святилище","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-pechat-kostey","n":"Печать Костей","l":2,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Фаланга пальца.","d":"8 часов","conc":false,"rit":true,"dmg":"3к6 колющий","cl":["Жрец","Паладин","Волшебник"],"ds":"Вы чертите печать на поверхности или проходе (до 6 м). Когда существо, не названное вами, пересекает её, вы мысленно пробуждаетесь/узнаёте об этом (если вы в пределах 1,5 км), а нарушитель совершает спасбросок (Телосложение): 3к6 урона (колющий) при провале, половина при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 2-го.","save":"Телосложение","atk":false,"mech":"Печать","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-kope-pustoty","n":"Копьё Пустоты","l":1,"sc":"Вызов","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к10 силовое поле","cl":["Чародей","Колдун","Волшебник"],"ds":"Дальнобойная атака заклинанием: при попадании 2к10 урона (силовое поле). При критическом попадании копьё пробивает цель и поражает второе существо в 3 м позади неё (обычный бросок атаки). На больших уровнях: +1к10 за каждый уровень ячейки выше 1-го.","save":"","atk":true,"mech":"Копьё","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-dvoynik-zvezd","n":"Двойник Звёзд","l":5,"sc":"Иллюзия","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"4к6 излучение","cl":["Бард","Жрец","Друид"],"ds":"Вы создаёте двойника из звёздного металла, светящегося тускло. Он двигается по вашей воле (бонусное действие, 9 м), вы видите и слышите его органами чувств, и ваши заклинания могут исходить от него. Двойник имеет КД 14 и 1 хит; при уничтожении взрывается: 4к6 урона (излучение) в 3 м.","save":"","atk":false,"mech":"Двойник","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-potok-razuma","n":"Поток Разума","l":3,"sc":"Очарование","t":"1 действие","r":"На себя (линия 30 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"7к6 психический","cl":["Чародей","Бард","Колдун"],"ds":"Линия длиной 30 м и шириной 1,5 м. Существа на линии совершают спасбросок (Интеллект): 7к6 урона (психический) при провале, половина при успехе. Поток игнорирует укрытие на половину и на три четверти. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Поток","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-uzy-yada","n":"Узы Яда","l":1,"sc":"Очарование","t":"1 действие","r":"18 м","c":"ВСМ","m":"Жало пчелы.","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"1к4 яд","cl":["Следопыт","Колдун","Друид"],"ds":"Узы (яда) охватывают существо: спасбросок (Телосложение) или оно опутано. В конце каждого своего хода цель повторяет спасбросок, оканчивая эффект при успехе. Пока цель опутана, она получает 1к4 урона (яд) в начале каждого своего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 1-го.","save":"Телосложение","atk":false,"mech":"Узы","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-raspad-voln","n":"Распад Волн","l":6,"sc":"Вызов","t":"1 действие","r":"18 м","c":"ВСМ","m":"Морская ракушка.","d":"Мгновенная","conc":false,"rit":false,"dmg":"10к10 дробящий","cl":["Чародей","Жрец"],"ds":"Существо совершает спасбросок Телосложения: 10к10 урона (дробящий) при провале, половина при успехе. Существо, у которого хиты опустились до 0, обращается в стихию и может быть возвращено только «Истинным воскрешением» или «Желанием». На больших уровнях: +1к10 за каждый уровень ячейки выше 6-го.","save":"Телосложение","atk":false,"mech":"Распад","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-duh-vetra","n":"Дух Ветра","l":3,"sc":"Вызов","t":"1 действие","r":"27 м","c":"ВСМ","m":"Перо.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8+6 звук","cl":["Следопыт","Друид","Волшебник"],"ds":"Вы призываете духа (ветра) Среднего размера: КД 13 + уровень заклинания, хиты 30 + 10 за уровень выше 3-го, скорость 12 м. Мультиатака: число атак, равное половине уровня заклинания; атака заклинанием +ваш бонус, 1к8 + 3 + уровень урона (звук). Иммунитет к урону «звук». Действует сразу после вас. На больших уровнях: +10 хитов и +1 КД за каждый уровень ячейки выше 3-го.","save":"","atk":true,"mech":"Дух","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-kleymo-kamnya","n":"Клеймо Камня","l":1,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 дробящий","cl":["Изобретатель","Следопыт","Паладин"],"ds":"Следующее ваше попадание атакой оружием наносит дополнительно 2к6 урона (дробящий), и цель совершает спасбросок (Сила) — при провале она сбивается с ног, если она Большая или меньше. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Сила","atk":false,"mech":"Клеймо","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-avatar-duhov","n":"Аватар Духов","l":6,"sc":"Преобразование","t":"1 бонусное действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"4к8 психический","cl":["Бард","Колдун"],"ds":"Вы становитесь аватаром стихии: иммунитет к урону «психический», полёт 18 м, 30 временных хитов. Бонусным действием в каждый ход вы метаете снаряд (дальнобойная атака заклинанием, 36 м) на 4к8 урона (психический). На больших уровнях: +10 временных хитов за каждый уровень ячейки выше 6-го.","save":"","atk":true,"mech":"Аватар","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-aura-mirazhey","n":"Аура Миражей","l":3,"sc":"Ограждение","t":"1 действие","r":"На себя (3 м)","c":"В","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"2к6 психический","cl":["Бард","Паладин","Следопыт"],"ds":"Вас окружает аура радиусом 3 м. Союзники в ней имеют сопротивление урону «психический» и преимущество на спасброски от эффектов, из-за которых цель видит ложные образы. Враг, начинающий ход в ауре, совершает спасбросок (Интеллект) или получает 2к6 урона (психический). На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Интеллект","atk":false,"mech":"Аура","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-golos-sveta","n":"Голос Света","l":1,"sc":"Очарование","t":"1 действие","r":"На себя","c":"В","m":"","d":"10 минут","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Чародей"],"ds":"Ваш голос наполняется силой стихии (света). Вы совершаете с преимуществом проверки Харизмы против существ, которые вас слышат; одно из них по вашему выбору совершает спасбросок Мудрости — при провале оно не может солгать вам до конца действия заклинания. По окончании существо знает, что на него влияли. На больших уровнях: +1 существо, которое не может лгать за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Голос","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-carstvo-shipov","n":"Царство Шипов","l":7,"sc":"Вызов","t":"1 минута","r":"Касание","c":"ВСМ","m":"Шип розы.","d":"1 день","conc":false,"rit":false,"dmg":"—","cl":["Друид","Бард"],"ds":"Вы и до 8 существ переноситесь в полуплан стихии (шипов) площадью 150 м², где вы задаёте погоду, свет и простой рельеф. Несогласное существо может избежать переноса спасброском Харизмы. По окончании все возвращаются туда, откуда ушли. Ячейкой 9 уровня — постоянно, с единственным входом.","save":"Сила","atk":false,"mech":"Царство","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-perenos-run","n":"Перенос Рун","l":3,"sc":"Вызов","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Жрец","Волшебник"],"ds":"Вы и до шести согласных существ, держащихся за руки, перемещаетесь по цепи рун на расстояние до 150 м в видимое или известное вам место. На больших уровнях: +150 м за каждый уровень ячейки выше 3-го.","save":"","atk":false,"mech":"Перенос","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-balzam-vremeni","n":"Бальзам Времени","l":1,"sc":"Воплощение","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"1 минута","conc":false,"rit":false,"dmg":"—","cl":["Бард","Следопыт","Друид"],"ds":"Существо восстанавливает 1к8 + модификатор заклинательной характеристики хитов и получает сопротивление урону «силовое поле» на 1 минуту. Не действует на нежить и конструктов. На больших уровнях: +1к8 за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Бальзам","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-slovo-teni","n":"Слово Тени","l":8,"sc":"Очарование","t":"1 действие","r":"На себя (18 м)","c":"В","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"13к6 некротика","cl":["Колдун","Бард"],"ds":"Вы произносите истинное слово (тени). Каждый враг в 18 м, слышащий вас, совершает спасбросок Харизмы: 13к6 урона (некротика) и ошеломление до конца вашего следующего хода при провале, половина урона при успехе.","save":"Харизма","atk":false,"mech":"Слово","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-oblik-krovi","n":"Облик Крови","l":4,"sc":"Преобразование","t":"1 действие","r":"На себя","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"2к8 некротика","cl":["Колдун","Жрец","Следопыт"],"ds":"Вы принимаете облик (крови): сопротивление урону «некротика» и немагическому оружию, скорость полёта или лазания 12 м, а действием вы совершаете две рукопашные атаки заклинанием по 2к8 урона (некротика). Попадание: цель не может восстанавливать хиты до конца своего следующего хода. На больших уровнях: +1к8 к одной атаке за каждый уровень ячейки выше 4-го.","save":"","atk":true,"mech":"Облик","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-cep-molniy","n":"Цепь Молний","l":2,"sc":"Воплощение","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"3к8 электричество","cl":["Чародей","Изобретатель","Друид"],"ds":"Дальнобойная атака заклинанием: 3к8 урона (электричество) при попадании. Затем цепь перескакивает на второе существо в 3 м от первой цели: оно совершает спасбросок (Ловкость) или получает половину этого урона. На больших уровнях: +1к8 и +1 перескок за каждый уровень ячейки выше 2-го.","save":"Ловкость","atk":true,"mech":"Цепь","theme":"Молний","orig":true,"pack":"spells9.js"},{"id":"sp9-iskra-groma","n":"Искра Грома","l":0,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к10 звук","cl":["Жрец","Бард","Чародей"],"ds":"Дальнобойная атака заклинанием по существу или предмету: при попадании 1к10 урона (звук). Предмет, который никто не несёт, получает двойной урон. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Искра","theme":"Грома","orig":true,"pack":"spells9.js"},{"id":"sp9-stena-ineya","n":"Стена Инея","l":4,"sc":"Воплощение","t":"1 действие","r":"36 м","c":"ВСМ","m":"Кристалл льда.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"5к8 холод","cl":["Чародей","Волшебник","Друид"],"ds":"Стена (инея) длиной до 18 м, высотой 6 м и толщиной 30 см (или кольцо диаметром 6 м). Существо, впервые за ход проходящее сквозь стену или оканчивающее ход в ней, совершает спасбросок (Телосложение): 5к8 урона (холод) при провале (и цель покрывается коркой льда: скорость уменьшается на 3 м до конца её следующего хода), половина при успехе. Стена — слабо заслоняет обзор. На больших уровнях: +1к8 за каждый уровень ячейки выше 4-го.","save":"Телосложение","atk":false,"mech":"Стена","theme":"Инея","orig":true,"pack":"spells9.js"},{"id":"sp9-oruzhie-plameni","n":"Оружие Пламени","l":2,"sc":"Преобразование","t":"1 бонусное действие","r":"Касание","c":"ВС","m":"","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к6 огонь","cl":["Изобретатель","Паладин","Следопыт"],"ds":"Немагическое оружие становится магическим с бонусом +1 к атаке и наносит дополнительно 1к6 урона (огонь). Один раз в ход при попадании владелец может заставить цель совершить спасбросок (Ловкость): при провале она загорается: 1к4 урона (огонь) в начале каждого своего хода, пока не потратит действие на тушение. Ячейкой 4–5 уровня бонус +2, 6+ уровня — +3.","save":"","atk":false,"mech":"Оружие","theme":"Пламени","orig":true,"pack":"spells9.js"},{"id":"sp9-kasanie-kostey","n":"Касание Костей","l":0,"sc":"Некромантия","t":"1 действие","r":"Касание","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"1к8 колющий","cl":["Жрец","Колдун","Волшебник"],"ds":"Рукопашная атака заклинанием: при попадании 1к8 урона (колющий), и цель становится хрупкой: следующий дробящий урон по ней до конца её следующего хода увеличивается на 1к6. Урон увеличивается на одну кость на 5, 11 и 17 уровнях.","save":"","atk":true,"mech":"Касание","theme":"Костей","orig":true,"pack":"spells9.js"},{"id":"sp9-tropa-pustoty","n":"Тропа Пустоты","l":4,"sc":"Преобразование","t":"10 минут","r":"Касание","c":"ВСМ","m":"Чёрная жемчужина.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Колдун","Волшебник","Паладин"],"ds":"До 8 согласных существ отправляются в путь сквозь пустоту: группа исчезает и появляется в месте, которое вы видели. На время действия скорость путешествия группы удваивается, а случайные столкновения в пути случаются вдвое реже.","save":"","atk":false,"mech":"Тропа","theme":"Пустоты","orig":true,"pack":"spells9.js"},{"id":"sp9-morok-zvezd","n":"Морок Звёзд","l":2,"sc":"Очарование","t":"1 действие","r":"27 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Бард","Жрец","Друид"],"ds":"Существо совершает спасбросок Мудрости. При провале в начале каждого своего хода оно бросает к6: на 1–2 оно атакует ближайшее существо (кроме себя) и больше ничего не делает. В конце хода оно повторяет спасбросок. При каждом провале повторного спасброска цель также очерчивается звёздным светом: атаки по ней совершаются с преимуществом до конца её следующего хода. На больших уровнях: +1 цель за каждый уровень ячейки выше 2-го.","save":"Мудрость","atk":false,"mech":"Морок","theme":"Звёзд","orig":true,"pack":"spells9.js"},{"id":"sp9-otmetina-razuma","n":"Отметина Разума","l":0,"sc":"Очарование","t":"1 бонусное действие","r":"18 м","c":"С","m":"","d":"1 раунд","conc":false,"rit":false,"dmg":"1к4 психический","cl":["Паладин","Следопыт","Изобретатель"],"ds":"Вы отмечаете существо знаком (разума). Первое попадание по нему атакой оружием (вашей или союзника) до конца вашего следующего хода наносит дополнительно 1к4 урона (психический). Нельзя накладывать на одно существо чаще раза в раунд. Кость урона растёт до к6, к8 и к10 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Отметина","theme":"Разума","orig":true,"pack":"spells9.js"},{"id":"sp9-kara-yada","n":"Кара Яда","l":5,"sc":"Преобразование","t":"1 действие","r":"36 м","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"8к8 яд","cl":["Изобретатель","Колдун","Друид"],"ds":"Одно существо совершает спасбросок (Телосложение): 8к8 урона (яд) при провале (и цель отравлена до конца своего следующего хода), половина при успехе. Если урон опускает хиты до 0, цель распадается, становясь прахом стихии. На больших уровнях: +1к8 за каждый уровень ячейки выше 5-го.","save":"Телосложение","atk":false,"mech":"Кара","theme":"Яда","orig":true,"pack":"spells9.js"},{"id":"sp9-strazh-voln","n":"Страж Волн","l":2,"sc":"Вызов","t":"1 действие","r":"9 м","c":"ВСМ","m":"Морская ракушка.","d":"Концентрация, до 1 часа","conc":true,"rit":false,"dmg":"1к8 дробящий","cl":["Жрец","Друид","Следопыт"],"ds":"Вы призываете крошечного духа (волн): КД 14, хиты 10, полёт 9 м, действует в ваш ход. Он может совершать действие Помощь или атаковать (атака заклинанием, 1,5 м, 1к8 урона (дробящий)). Реакцией дух бьёт существо, атакующее вас в 1,5 м от него. На больших уровнях: +5 хитов и +1к8 к урону за каждый уровень ячейки выше 2-го.","save":"","atk":true,"mech":"Страж","theme":"Волн","orig":true,"pack":"spells9.js"},{"id":"sp9-obereg-vetra","n":"Оберег Ветра","l":0,"sc":"Воплощение","t":"1 реакция (когда вы получаете урон)","r":"На себя","c":"С","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"—","cl":["Паладин","Жрец","Волшебник"],"ds":"Вы уменьшаете полученный урон на 1к6 + модификатор заклинательной характеристики. Если урон был типа «звук», уменьшение удваивается. Кость растёт до 2к6, 3к6 и 4к6 на 5, 11 и 17 уровнях.","save":"","atk":false,"mech":"Оберег","theme":"Ветра","orig":true,"pack":"spells9.js"},{"id":"sp9-svyatilische-kamnya","n":"Святилище Камня","l":5,"sc":"Ограждение","t":"10 минут","r":"Касание","c":"ВСМ","m":"Кусочек гранита.","d":"24 часа","conc":false,"rit":false,"dmg":"—","cl":["Изобретатель","Паладин","Волшебник"],"ds":"Область радиусом 15 м становится святилищем стихии. Союзники в ней получают +1 к КД и спасброскам; враги, входящие в область, совершают спасбросок (Сила) — при провале они сбивается с ног, если она Большая или меньше и у них помеха на атаки по союзникам до конца хода. Ячейкой 7+ уровня длится 7 дней, 9 уровня — постоянно.","save":"Сила","atk":false,"mech":"Святилище","theme":"Камня","orig":true,"pack":"spells9.js"},{"id":"sp9-vzryv-duhov","n":"Взрыв Духов","l":3,"sc":"Вызов","t":"1 действие","r":"45 м","c":"ВСМ","m":"Благовония.","d":"Мгновенная","conc":false,"rit":false,"dmg":"6к6 психический","cl":["Бард","Колдун","Жрец"],"ds":"Сфера радиусом 6 м: каждое существо совершает спасбросок (Мудрость), получая 6к6 урона (психический) при провале (и цель испугана вами до конца её следующего хода) или половину при успехе. На больших уровнях: +1к6 за каждый уровень ячейки выше 3-го.","save":"Мудрость","atk":false,"mech":"Взрыв","theme":"Духов","orig":true,"pack":"spells9.js"},{"id":"sp9-volna-mirazhey","n":"Волна Миражей","l":1,"sc":"Иллюзия","t":"1 действие","r":"На себя (конус 4,5 м)","c":"ВС","m":"","d":"Мгновенная","conc":false,"rit":false,"dmg":"2к6 психический","cl":["Бард","Колдун","Волшебник"],"ds":"Существа в конусе совершают спасбросок (Интеллект): при провале 2к6 урона (психический) и цель видит ложные образы: помеха на следующий бросок атаки до конца её следующего хода; при успехе — половина урона без дополнительного эффекта. На больших уровнях: +1к6 за каждый уровень ячейки выше 1-го.","save":"Интеллект","atk":false,"mech":"Волна","theme":"Миражей","orig":true,"pack":"spells9.js"},{"id":"sp9-svyaz-sveta","n":"Связь Света","l":5,"sc":"Прорицание","t":"10 минут","r":"Неограниченная","c":"ВСМ","m":"Святой символ.","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Паладин","Жрец","Бард"],"ds":"Вы вопрошаете святое место или символ (божество отвечает видением), но в любом месте плана, где бывали. Вы видите и слышите место, как если бы находились там, и можете говорить с присутствующими.","save":"","atk":false,"mech":"Связь","theme":"Света","orig":true,"pack":"spells9.js"},{"id":"sp9-kokon-shipov","n":"Кокон Шипов","l":3,"sc":"Ограждение","t":"1 действие","r":"18 м","c":"ВС","m":"","d":"Концентрация, до 1 минуты","conc":true,"rit":false,"dmg":"—","cl":["Следопыт","Друид","Паладин"],"ds":"Кокон (шипов) окружает существо. Согласное существо получает полное укрытие и 2к10 временных хитов. Несогласное совершает спасбросок (Сила) — при провале оно опутано, имеет полное укрытие и не может колдовать заклинания с соматическим компонентом; в конце каждого хода повторяет спасбросок. На больших уровнях: +1 цель за каждый уровень ячейки выше 3-го.","save":"Сила","atk":false,"mech":"Кокон","theme":"Шипов","orig":true,"pack":"spells9.js"},{"id":"sp9-pokrov-run","n":"Покров Рун","l":1,"sc":"Ограждение","t":"1 действие","r":"На себя","c":"ВСМ","m":"Резец и кусочек кости.","d":"1 час","conc":false,"rit":false,"dmg":"5 силовое поле","cl":["Изобретатель","Жрец","Волшебник"],"ds":"Вы получаете 5 временных хитов. Пока они есть, существо, попавшее по вам рукопашной атакой, получает 5 урона (силовое поле); у вас сопротивление урону «силовое поле». На больших уровнях: +5 временных хитов и +5 ответного урона за каждый уровень ячейки выше 1-го.","save":"","atk":false,"mech":"Покров","theme":"Рун","orig":true,"pack":"spells9.js"},{"id":"sp9-kolco-vremeni","n":"Кольцо Времени","l":6,"sc":"Преобразование","t":"1 действие","r":"45 м","c":"ВСМ","m":"Песчинка из песочных часов.","d":"Концентрация, до 10 минут","conc":true,"rit":false,"dmg":"6к8 силовое поле","cl":["Бард","Волшебник"],"ds":"Кольцо радиусом до 18 м. Существо внутри не может пересечь кольцо без спасброска (Мудрость): при провале оно получает 6к8 урона (силовое поле), не проходит и замедляется: не может совершать бонусных действий до конца своего следующего хода; при успехе — половина урона и проходит. Вы выбираете существ, которых кольцо пропускает. На больших уровнях: +1к8 за каждый уровень ячейки выше 6-го.","save":"Мудрость","atk":false,"mech":"Кольцо","theme":"Времени","orig":true,"pack":"spells9.js"},{"id":"sp9-ubezhische-teni","n":"Убежище Тени","l":3,"sc":"Ограждение","t":"1 минута","r":"На себя (полусфера 3 м)","c":"ВСМ","m":"Клочок чёрной ткани.","d":"8 часов","conc":false,"rit":true,"dmg":"—","cl":["Следопыт","Колдун","Паладин"],"ds":"Над вами возникает неподвижное убежище для 9 Средних существ: вход скрыт тьмой, изнутри видно наружу, а снаружи — нет. Существа и предметы внутри при сотворении могут свободно выходить и входить; прочие — нет. Магия не проходит сквозь стены.","save":"","atk":false,"mech":"Убежище","theme":"Тени","orig":true,"pack":"spells9.js"},{"id":"sp9-chute-krovi","n":"Чутьё Крови","l":1,"sc":"Прорицание","t":"1 действие","r":"На себя (9 м)","c":"ВС","m":"","d":"Концентрация, до 10 минут","conc":true,"rit":true,"dmg":"—","cl":["Колдун","Жрец","Бард"],"ds":"Вы чувствуете живых существ, их раны и следы крови за последние 24 часа в пределах 9 м и знаете их направление. Чутьё проходит сквозь большинство преград, но блокируется 30 см камня, 2,5 см металла или тонким листом свинца.","save":"","atk":false,"mech":"Чутьё","theme":"Крови","orig":true,"pack":"spells9.js"},{"id":"sp9-katastrofa-molniy","n":"Катастрофа Молний","l":7,"sc":"Воплощение","t":"1 действие","r":"300 м","c":"ВСМ","m":"Кусочек янтаря.","d":"Мгновенная","conc":false,"rit":false,"dmg":"12к6 электричество","cl":["Чародей","Друид"],"ds":"Сфера радиусом 12 м: существа совершают спасбросок (Ловкость) — 12к6 урона (электричество) при провале (и цель не может совершать реакции до начала своего следующего хода), половина при успехе. Местность становится труднопроходимой на 1 час. На больших уровнях: +1к6 за каждый уровень ячейки выше 7-го.","save":"Ловкость","atk":false,"mech":"Катастрофа","theme":"Молний","orig":true,"pack":"spells9.js"}];const D=window.DATA=window.DATA||{};D.spells=D.spells||[];const ids=new Set(D.spells.map(s=>s.id));A.forEach(s=>{if(!ids.has(s.id))D.spells.push(s)});})();
